      'faq_app_crash_a': 'कृपया ऐप को नवीनतम संस्करण में अपडेट करें, डिवाइस रीस्टार्ट करें और कैशे साफ़ करें। समस्या बनी रहे तो सहायता से संपर्क करें।',
      'faq_change_username_q': 'मैं अपना उपयोगकर्ता नाम कैसे बदलूँ?',
