      'faq_delete_account_q': 'मैं अपना खाता स्थायी रूप से कैसे हटाऊँ?',
      'faq_delete_account_a': 'सेटिंग्स > खाता हटाएं पर जाएँ और निर्देशों का पालन करें। यह क्रिया पूर्ववत नहीं की जा सकती।',
      'faq_fake_account_q': 'मैं नकली खाते की शिकायत कैसे करूँ?',
      'faq_fake_account_a': 'प्रोफ़ाइल खोलें, मेनू पर टैप करें और रिपोर्ट > नकली खाता चुनें। टीम समीक्षा करेगी।',
