      'faq_harassment_a': 'तुरंत उपयोगकर्ता को ब्लॉक करें और रिपोर्ट करें। हम उत्पीड़न को गंभीरता से लेते हैं और जाँच करेंगे।',
      'faq_notification_q': 'मुझे सूचनाएँ नहीं मिल रहीं। क्यों?',
