      'faq_otp_expired_q': 'मेरा OTP समाप्त हो गया है। मुझे क्या करना चाहिए?',
      'faq_otp_expired_a': 'नया कोड पाने के लिए "OTP दोबारा भेजें" पर टैप करें और समय सीमा के भीतर दर्ज करें।',
      'faq_otp_not_received_q': 'मुझे OTP नहीं मिला। मुझे क्या करना चाहिए?',
      'faq_otp_not_received_a': 'अपना नेटवर्क और स्पैम फ़ोल्डर जाँचें। एक मिनट प्रतीक्षा करें और "OTP दोबारा भेजें" पर टैप करें। समस्या बनी रहे तो सहायता से संपर्क करें।',
      'faq_post_upload_q': 'मैं अपनी पोस्ट अपलोड नहीं कर पा रहा हूँ। क्यों?',
      'faq_post_upload_a': 'अपना इंटरनेट कनेक्शन और फ़ाइल का आकार जाँचें। कुछ फ़ॉर्मैट समर्थित नहीं हो सकते। पुनः प्रयास करें या सहायता से संपर्क करें।',
      'faq_privacy_settings_q': 'मैं अपनी गोपनीयता सेटिंग्स कैसे बदलूँ?',
      'faq_privacy_settings_a': 'प्रोफ़ाइल > गोपनीयता पर जाकर चुनें कि आपकी पोस्ट कौन देख सकता है और आपको संदेश भेज सकता है।',
